from pathlib import Path
import re

p=Path('index.html')
s=p.read_text(encoding='utf-8')

s=s.replace("await loadData();await repairLegacyGeneralCollections();await loadData();show(savedPage())","await loadData();show(savedPage())")

s=re.sub(r"async function saveSale\(\)\{.*?\n\}function v16DateOnly", '''async function saveSale(){try{\n const q=Number(document.getElementById('s_kg')?.value||0),p=Number(document.getElementById('s_price')?.value||0),vatRate=Number(document.getElementById('s_vat')?.value||0),payment=document.getElementById('s_payment')?.value||'Peşin',due=document.getElementById('s_due')?.value||null;\n if(!data.customers.length)return alert('Önce müşteri ekleyin.');\n if(!(q>0&&p>=0))return alert('Kg ve fiyatı kontrol edin.');\n if(q>Number(data.stockQty||0))return alert('Yeterli stok yok.');\n if(payment==='Vadeli'&&!due)return alert('Vade tarihi girin.');\n if(payment!=='Vadeli'&&due)return alert('Peşin satışta vade tarihi boş olmalıdır.');\n if(!warehouse?.id||!product?.id||!currentUser?.id)throw new Error('Depo, ürün veya kullanıcı bilgisi hazır değil.');\n const {error}=await client.rpc('record_sale',{p_customer_id:document.getElementById('s_customer').value,p_warehouse_id:warehouse.id,p_product_id:product.id,p_sale_date:document.getElementById('s_date').value,p_payment_type:payment,p_due_date:due,p_quantity:q,p_unit_price:p,p_vat_rate:vatRate,p_created_by:currentUser.id,p_notes:null});\n if(error)throw error; await loadData(); alert('Satış buluta güvenli şekilde kaydedildi.'); show('dashboard');\n}catch(e){alert(msg(e))}}\nfunction v16DateOnly''', s, flags=re.S)

s=re.sub(r"async function addPurchase\(\)\{.*?\n\}function expenses", '''async function addPurchase(){try{\n const q=Number(document.getElementById('p_kg')?.value||0),pr=Number(document.getElementById('p_price')?.value||0),vatRate=Number(document.getElementById('p_vat')?.value||0),extra=Number(document.getElementById('p_extra')?.value||0);\n if(!(q>0&&pr>=0&&extra>=0))return alert('Kg, alış fiyatı ve ek maliyeti kontrol edin.');\n if(!warehouse?.id||!product?.id||!currentUser?.id)throw new Error('Depo, ürün veya kullanıcı bilgisi hazır değil.');\n const {error}=await client.rpc('record_purchase',{p_warehouse_id:warehouse.id,p_product_id:product.id,p_purchase_date:document.getElementById('p_date').value,p_quantity:q,p_unit_price:pr,p_vat_rate:vatRate,p_extra_cost:extra,p_created_by:currentUser.id,p_supplier_name:null,p_notes:null});\n if(error)throw error; await loadData(); alert('Alış buluta güvenli şekilde kaydedildi.'); show('purchases');\n}catch(e){alert(msg(e))}}\nfunction expenses''', s, flags=re.S)

final=r'''\n<script>\n/* CARBONERP_V20_FINAL */\n(function(){\n const activeSale=s=>!!s&&s.status!=='cancelled';\n const activeCollection=c=>!!c&&c.status!=='cancelled';\n const salesActive=()=> (data.sales||[]).filter(activeSale);\n const collectionsActive=()=> (data.collections||[]).filter(activeCollection);\n const saleCollected=id=>collectionsActive().filter(c=>c.sale_id===id).reduce((a,c)=>a+Number(c.amount||0),0);\n const saleOutstanding=s=>activeSale(s)?Math.max(0,Number(s.total||0)-saleCollected(s.id)):0;\n const qtyOf=s=>(s.sale_items||[]).reduce((a,i)=>a+Number(i.quantity||0),0);\n window.saleCollected=saleCollected;\n window.saleOutstanding=saleOutstanding;\n window.customerBalance=id=>salesActive().filter(s=>s.customer_id===id).reduce((a,s)=>a+Number(s.total||0),0)-collectionsActive().filter(c=>c.customer_id===id).reduce((a,c)=>a+Number(c.amount||0),0);\n window.totalReceivable=()=>salesActive().reduce((a,s)=>a+Number(s.total||0),0)-collectionsActive().reduce((a,c)=>a+Number(c.amount||0),0);\n window.overdueSales=()=>salesActive().filter(s=>s.due_date&&saleOutstanding(s)>0&&s.due_date<today());\n window.dueTodaySales=()=>salesActive().filter(s=>s.due_date===today()&&saleOutstanding(s)>0);\n window.v16OpenSales=()=>salesActive().filter(s=>saleOutstanding(s)>0&&s.due_date);\n window.monthlySummary=function(){\n  const map={}; salesActive().forEach(s=>{const k=String(s.sale_date||'').slice(0,7);if(!k)return;if(!map[k])map[k]={sales:0,cost:0,kg:0};map[k].sales+=Number(s.subtotal||0);map[k].cost+=Number(s.cost_total||0);map[k].kg+=qtyOf(s)});\n  return Object.keys(map).sort().slice(-6).map(k=>{const x=map[k],profit=x.sales-x.cost;return {k:k,sales:x.sales,cost:x.cost,kg:x.kg,profit:profit,margin:x.sales?profit/x.sales*100:0}});\n };\n window.salesPerformance=function(s){\n  s=s.filter(activeSale); if(!s.length)return '<div class="empty">Bu dönemde satış yok.</div>';\n  const kg=s.reduce((z,x)=>z+qtyOf(x),0),revenue=s.reduce((z,x)=>z+Number(x.subtotal||0),0),cost=s.reduce((z,x)=>z+Number(x.cost_total||0),0),profit=revenue-cost,avgKg=kg?revenue/kg:0,margin=revenue?profit/revenue*100:0;\n  return '<table><tr><th>Gösterge</th><th>Sonuç</th></tr><tr><td>Satış adedi</td><td>'+s.length+'</td></tr><tr><td>Satılan miktar</td><td>'+kg.toLocaleString('tr-TR')+' kg</td></tr><tr><td>Ortalama satış fiyatı</td><td>'+money(avgKg)+'/kg</td></tr><tr><td>Brüt kâr</td><td>'+money(profit)+'</td></tr><tr><td>Brüt kâr marjı</td><td>%'+margin.toFixed(1)+'</td></tr></table>';\n };\n window.customerProfit=function(s){\n  s=s.filter(activeSale); const ids=[...new Set(s.map(x=>x.customer_id))]; if(!ids.length)return '<div class="empty">Satış yok.</div>';\n  const rows=ids.map(id=>{const a=s.filter(x=>x.customer_id===id),kg=a.reduce((z,x)=>z+qtyOf(x),0),r=a.reduce((z,x)=>z+Number(x.subtotal||0),0),c=a.reduce((z,x)=>z+Number(x.cost_total||0),0),p=r-c,m=r?p/r*100:0;return '<tr><td>'+esc(customerName(id))+'</td><td>'+kg.toLocaleString('tr-TR')+'</td><td>'+money(r)+'</td><td>'+money(c)+'</td><td class="'+(p>=0?'positive':'danger')+'">'+money(p)+'</td><td>%'+m.toFixed(1)+'</td></tr>'}).join('');\n  return '<table><tr><th>Müşteri</th><th>Kg</th><th>Ciro (KDV hariç)</th><th>Maliyet</th><th>Brüt Kâr</th><th>Marj</th></tr>'+rows+'</table>';\n };\n window.customerTable=function(){\n  const cs=data.customers||[]; if(!cs.length)return '<div class="empty">Henüz müşteri yok.</div>';\n  const rows=cs.map(c=>{const ss=salesActive().filter(s=>s.customer_id===c.id),cc=collectionsActive().filter(x=>x.customer_id===c.id),s=ss.reduce((a,x)=>a+Number(x.total||0),0),p=cc.reduce((a,x)=>a+Number(x.amount||0),0),b=s-p;return '<tr><td>'+esc(c.name)+'</td><td>'+esc(c.phone||'')+'</td><td>'+money(s)+'</td><td>'+money(p)+'</td><td class="'+(b>0?'warning':'positive')+'">'+money(b)+'</td><td><button class="btn secondary" onclick="customerDetail(\''+c.id+'\')">Ekstre</button></td></tr>'}).join('');\n  return '<table><tr><th>Müşteri</th><th>Telefon</th><th>Satış</th><th>Tahsilat</th><th>Bakiye</th><th></th></tr>'+rows+'</table>';\n };\n window.repairLegacyGeneralCollections=async()=>false;\n})();\n</script>\n'''
s=re.sub(r'\s*</body>\s*</html>\s*$',final+'\n</body>\n</html>\n',s,flags=re.S)
p.write_text(s,encoding='utf-8')
print('finalize_v20 complete')
